SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_death28th(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) NOT NULL,
  date_com varchar(14) NOT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_death28th WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_death28th
(
SELECT
	 @id,b.hospcode
   ,CONCAT(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) areacode
   ,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com
	,@b_year+543 as b_year
  ,b.target,a.result
FROM
(
SELECT bhosp hospcode ,SUM(lborn) as target
FROM tmp_labor_hosp WHERE nation IN(99)
GROUP BY bhosp 
) b LEFT JOIN (
SELECT d.HOSPCODE,COUNT(DISTINCT d.hospcode,d.pid) result
FROM t_death28 d  INNER JOIN t_person_db p ON d.hospcode=p.hospcode AND d.pid=p.pid
WHERE p.NATION IN(99)
GROUP BY d.HOSPCODE
) a ON a.hospcode=b.hospcode
INNER JOIN chospital h ON b.hospcode=h.hoscode 
WHERE h.provcode in(@prov_c)
GROUP BY b.hospcode
);
